import{_ as t,o,c as s,a1 as a}from"./chunks/framework.DceXOx8u.js";const u=JSON.parse('{"title":"Upgrade to stable: behaviour changes","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://andresayac.github.io/botmesh/guide/migration-2"}],["meta",{"property":"og:url","content":"https://andresayac.github.io/botmesh/guide/migration-2"}]]},"headers":[],"relativePath":"guide/migration-2.md","filePath":"guide/migration-2.md"}'),i={name:"guide/migration-2.md"};function d(n,e,r,c,h,l){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="upgrade-to-stable-behaviour-changes" tabindex="-1">Upgrade to stable: behaviour changes <a class="header-anchor" href="#upgrade-to-stable-behaviour-changes" aria-label="Permalink to &quot;Upgrade to stable: behaviour changes&quot;">​</a></h1><p>Step 5 of the <a href="./stable-migration#upgrade-checklist">upgrade checklist</a>. <code>@botmesh/core</code> 2.0 leaves the alpha series with a few deliberate behaviour changes. This page lists each one, what changed and how to keep the old behaviour where that is still possible. Most bots need at most two edits: <code>lang: &#39;es&#39;</code> if the bot speaks Spanish, and <code>maxAttempts</code> where a wait set <code>retries</code>.</p><table tabindex="0"><thead><tr><th>Change</th><th>Who is affected</th><th>What to do</th></tr></thead><tbody><tr><td><a href="#built-in-texts-default-to-english">Built-in texts default to English</a></td><td>Bots that relied on the Spanish defaults</td><td>Add <code>lang: &#39;es&#39;</code></td></tr><tr><td><a href="#retries-and-maxattempts"><code>retries</code> and <code>maxAttempts</code></a></td><td>Waits, forms and JSON flows that set <code>retries</code></td><td>Rename <code>retries: N</code> to <code>maxAttempts: N</code></td></tr><tr><td><a href="#sends-need-a-running-bot">Sends need a running bot</a></td><td>Code that sends before <code>start()</code> or after <code>stop()</code></td><td>Send after <code>start()</code>, or catch <code>BotNotRunningError</code></td></tr><tr><td><a href="#flow-definitions-are-checked-when-built">Flow definitions are checked when built</a></td><td><code>choose({})</code>, <code>ask(text, &#39;&#39;)</code></td><td>Fix the definition</td></tr><tr><td><a href="#rate-limited-ctx-sends-retry-once">Rate-limited <code>ctx</code> sends retry once</a></td><td>Bots on transports that answer 429</td><td>Nothing, or tune <code>rateLimitRetry</code></td></tr><tr><td><a href="#invalid-provider-events">Invalid provider events</a></td><td>Custom providers</td><td>Emit well-formed events</td></tr><tr><td><a href="#a-hook-that-calls-next-twice">A hook that calls <code>next()</code> twice</a></td><td>Hooks with that bug</td><td>Call <code>next()</code> once</td></tr><tr><td><a href="#ids-in-logs-are-hashed">Ids in logs are hashed</a></td><td>Log searches by phone number or chat id</td><td><code>logIds: &#39;raw&#39;</code> for local debugging</td></tr><tr><td><a href="#corrupt-append-logs">Corrupt append logs</a></td><td><code>FileDurability</code> / <code>SharedFileEventJournal</code> with <code>appendLog</code></td><td>Repair the log if open refuses it</td></tr><tr><td><a href="#memorycoordinationhub-evicts-idle-chats"><code>MemoryCoordinationHub</code> evicts idle chats</a></td><td>Tests that inspect the hub</td><td>Nothing</td></tr><tr><td><a href="#broadcast-retries"><code>broadcast({ maxRetries })</code></a></td><td>Broadcasts</td><td>Rename to <code>retries</code> (alias kept)</td></tr><tr><td><a href="#whatsapp-flow-labels-default-to-english">WhatsApp Flow labels default to English</a></td><td><code>@botmesh/meta</code> forms published with <code>toFlowJson</code> / <code>publishForm</code></td><td>Pass <code>lang: &#39;es&#39;</code></td></tr><tr><td><a href="#presence-hints-while-disconnected">Presence hints while disconnected</a></td><td>Code that expected <code>typing()</code> / <code>markRead()</code> to throw while offline; custom providers</td><td>Nothing; custom providers resolve while not connected</td></tr><tr><td><a href="#stopping-event"><code>&#39;stopping&#39;</code> event</a></td><td>Plugins that cancel work on <code>&#39;stopped&#39;</code></td><td>Listen to <code>&#39;stopping&#39;</code> to cancel before the transport stops</td></tr><tr><td><a href="#persistent-flows-checkpoint-when-they-start">Persistent flows checkpoint when they start</a></td><td>Stores that count checkpoint writes</td><td>Nothing (one more write per flow entry)</td></tr><tr><td><a href="#error-messages-without-chat-ids">Error messages without chat ids</a></td><td>Code that parsed the chat out of an error message</td><td>Read <code>error.chatId</code></td></tr><tr><td><a href="#smaller-fixes">Smaller fixes</a></td><td><code>ctx.delete()</code> after <code>stop()</code>, <code>ctx.acknowledge</code>, unknown event kinds, <code>lang</code> + <code>i18n.defaultLocale</code>, <code>ChaosProvider.selfId</code></td><td>See the section</td></tr></tbody></table><h2 id="built-in-texts-default-to-english" tabindex="-1">Built-in texts default to English <a class="header-anchor" href="#built-in-texts-default-to-english" aria-label="Permalink to &quot;Built-in texts default to English&quot;">​</a></h2><p>The texts the core writes for you (conversation timeout, &quot;too many attempts&quot;, wait prompts, slash-command replies, form hints and the form skip word) used to be Spanish unless the bot configured i18n. They are now English: the skip word is <code>skip</code>, the retries message is <code>❌ Too many attempts. Conversation ended.</code>, and so on. <code>@botmesh/ai</code> follows: its built-in texts (confirmation prompt, Yes/No buttons, fallback replies, sources line) are English when no language is known.</p><p>The Spanish texts are still bundled. One option brings them back, without turning on per-user language resolution:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> bot</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Bot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ provider, lang: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;es&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><p><code>i18n: { defaultLocale: &#39;es&#39; }</code> also works, but it turns on language resolution (stored preference, client language, detector). See <a href="./i18n#a-single-language-bot-lang">Internationalization</a>. The project templates of <code>create-botmesh</code> already set <code>lang: &#39;es&#39;</code>.</p><h2 id="retries-and-maxattempts" tabindex="-1"><code>retries</code> and <code>maxAttempts</code> <a class="header-anchor" href="#retries-and-maxattempts" aria-label="Permalink to &quot;`retries` and `maxAttempts`&quot;">​</a></h2><p>Every <code>retries</code> option now means the same thing: attempts <strong>after</strong> the first one. That was already the case for <code>durability.outbox.retries</code>, but on waits (<code>ask</code>, <code>waitText</code>, <code>choose</code>…), form steps and JSON flow <code>ask</code>/<code>form</code> steps <code>retries: N</code> meant N answers in total. The total has its own option:</p><ul><li><code>maxAttempts: N</code>: the wait accepts N answers in total, the first included.</li><li><code>retries: N</code>: the same as <code>maxAttempts: N + 1</code>.</li></ul><p>The default does not change (3 answers in total). To keep the alpha behaviour, rename the option:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 2.0 alpha: 3 answers in total</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;x&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ask</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Email?&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;email&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { validate, retries: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 2.0: the same</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;x&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ask</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Email?&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;email&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { validate, maxAttempts: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><p>Passing both with values that disagree throws a <code>TypeError</code>. Invalid values (<code>maxAttempts: 0</code>, <code>retries: -1</code>) throw when the flow is defined. <code>bot.broadcast()</code> follows the same convention (see <a href="#broadcast-retries">below</a>).</p><p>Code you have not renamed yet keeps running with one more answer than before. To make that visible, the bot logs <strong>one warning</strong> (<code>logger.warn</code>, once per bot) the first time a wait, form or flow step sets <code>retries</code> without <code>maxAttempts</code>. Setting <code>maxAttempts</code> (alone, or together with a matching <code>retries</code>) silences it.</p><p>JSON flow documents (<code>@botmesh/flow-schema</code>, stored by the manager and <code>@botmesh/deployments</code>) do not change meaning: the format moves to <strong>version 2</strong>, and a version 1 document is migrated when it is loaded (<code>validateFlowDocument</code>, <code>compileFlowDocument</code>, <code>flowFromArtifact</code>, or explicitly with <code>migrateFlowDocument</code>). The 1 → 2 migration rewrites <code>retries: N</code> to <code>maxAttempts: N</code> (an old <code>retries: 0</code> behaved like 1 and becomes <code>maxAttempts: 1</code>), so published v1 flows keep their budget. In a version 2 document <code>retries</code> has the new meaning. <code>isFlowDocument()</code> only accepts the current version.</p><h2 id="sends-need-a-running-bot" tabindex="-1">Sends need a running bot <a class="header-anchor" href="#sends-need-a-running-bot" aria-label="Permalink to &quot;Sends need a running bot&quot;">​</a></h2><p><code>bot.send()</code>, <code>ctx.reply()</code>, edits and stream updates made before <code>bot.start()</code> (or after a failed start) or after <code>bot.stop()</code> used to reach the provider. They now reject with <code>BotNotRunningError</code> (<code>code: &#39;BOT_NOT_RUNNING&#39;</code>) and send nothing. Sends are accepted from the moment the transport starts connecting, so a <code>&#39;ready&#39;</code> listener can still send.</p><p>Concurrent <code>start()</code> / <code>stop()</code> calls run one at a time in call order: the last call decides the final state (<code>start(); stop(); start()</code> ends running).</p><h2 id="flow-definitions-are-checked-when-built" tabindex="-1">Flow definitions are checked when built <a class="header-anchor" href="#flow-definitions-are-checked-when-built" aria-label="Permalink to &quot;Flow definitions are checked when built&quot;">​</a></h2><p>These used to fail only when a user reached the step. They now throw a <code>TypeError</code> when the flow is defined:</p><ul><li><code>.choose(prompt, {})</code> (no options), a non-object <code>options</code>, or an option without a label;</li><li><code>.ask(text, &#39;&#39;)</code> or <code>.choose(prompt, options, &#39;&#39;)</code> (empty state key);</li><li>invalid <code>maxAttempts</code> / <code>retries</code> on <code>.ask()</code>, <code>.choose()</code> and <code>.form()</code>.</li></ul><h2 id="rate-limited-ctx-sends-retry-once" tabindex="-1">Rate-limited <code>ctx</code> sends retry once <a class="header-anchor" href="#rate-limited-ctx-sends-retry-once" aria-label="Permalink to &quot;Rate-limited `ctx` sends retry once&quot;">​</a></h2><p>A <code>ctx</code> send (in a handler, a flow or a conversation) rejected with a <code>RateLimitedError</code> asking for a wait of at most 5 s is retried in place. The alphas retried twice; 2.0 retries once by default and makes it configurable:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Bot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ provider, rateLimitRetry: { retries: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, maxWaitMs: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;10s&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } })</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Bot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ provider, rateLimitRetry: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// never retry in place</span></span></code></pre></div><p><code>bot.send()</code> is not retried (broadcasts and the durable outbox have their own back-off).</p><h2 id="invalid-provider-events" tabindex="-1">Invalid provider events <a class="header-anchor" href="#invalid-provider-events" aria-label="Permalink to &quot;Invalid provider events&quot;">​</a></h2><p>An event that breaks the normalized contract (not an object, a <code>kind</code> that is not a string, a message without <code>chatId</code>, <code>ref</code>, <code>senderId</code>, <code>type</code> or <code>body</code>…) used to fail deep in the pipeline with a generic <code>TypeError</code>. It is now dropped and reported once on the <code>&#39;error&#39;</code> event as an <code>InvalidProviderEventError</code>, which names the provider and the broken field (never ids or message contents). An event whose <code>kind</code> is a string this core does not know (a newer provider) is not an error: it is ignored, with a debug log line, so providers can add event kinds without breaking older cores.</p><h2 id="a-hook-that-calls-next-twice" tabindex="-1">A hook that calls <code>next()</code> twice <a class="header-anchor" href="#a-hook-that-calls-next-twice" aria-label="Permalink to &quot;A hook that calls `next()` twice&quot;">​</a></h2><p>A <code>before</code> hook that called <code>next()</code> twice threw <code>next() called multiple times</code> and the message was dropped. The first dispatch is now kept (the rest of the chain runs once, every later <code>next()</code> returns the same promise) and the misuse is reported on the <code>&#39;error&#39;</code> event.</p><h2 id="ids-in-logs-are-hashed" tabindex="-1">Ids in logs are hashed <a class="header-anchor" href="#ids-in-logs-are-hashed" aria-label="Permalink to &quot;Ids in logs are hashed&quot;">​</a></h2><p>The bot&#39;s own log lines (access-list and handoff drops, &quot;dispatching message&quot;, typing failures, conversation keys) carried raw chat and sender ids: phone numbers or emails. They now go through an ids policy, <code>BotConfig.logIds</code>:</p><ul><li><code>&#39;hash&#39;</code> (default): HMAC-SHA256, 16 characters, stable within the process. With tracing on it is the same hash as the spans (<code>telemetry.idKey</code> is reused).</li><li><code>&#39;raw&#39;</code>: the ids as they are, for local debugging.</li><li><code>&#39;omit&#39;</code>: no ids at all.</li></ul><h2 id="corrupt-append-logs" tabindex="-1">Corrupt append logs <a class="header-anchor" href="#corrupt-append-logs" aria-label="Permalink to &quot;Corrupt append logs&quot;">​</a></h2><p>With <code>appendLog</code>, a bad line at the <strong>end</strong> of <code>&lt;file&gt;.log</code> is a torn write and is cut, as before. A bad line in the <strong>middle</strong> was treated the same way, which silently dropped every later entry. <code>FileDurability.open()</code> and <code>SharedFileEventJournal.open()</code> now refuse such a log with an error whose <code>code</code> is <code>&#39;APPEND_LOG_CORRUPT&#39;</code> (it names the file, the line and the byte offset) and leave the file untouched: restore it from a backup, or cut it at that line.</p><p>Snapshots can now be flushed to disk before they replace the previous one: <code>FileDurability.open(path, { fsync: true })</code>, and the same <code>fsync</code> option on <code>FileEventJournal</code> and <code>SharedFileEventJournal</code>.</p><h2 id="memorycoordinationhub-evicts-idle-chats" tabindex="-1"><code>MemoryCoordinationHub</code> evicts idle chats <a class="header-anchor" href="#memorycoordinationhub-evicts-idle-chats" aria-label="Permalink to &quot;`MemoryCoordinationHub` evicts idle chats&quot;">​</a></h2><p>The in-process coordination hub kept per-chat state forever. It now evicts idle chats beyond <code>maxIdleKeys</code> (default 10,000, <code>Infinity</code> keeps them all). Fences stay monotonic across an eviction; a re-created chat reports <code>previousHolder: null</code>, so its next holder refreshes its state. The chat being used is never evicted, so <code>maxIdleKeys: 0</code> keeps only the most recent idle chat.</p><h2 id="broadcast-retries" tabindex="-1"><code>broadcast</code> retries <a class="header-anchor" href="#broadcast-retries" aria-label="Permalink to &quot;`broadcast` retries {#broadcast-retries}&quot;">​</a></h2><p><code>bot.broadcast(ids, content, { maxRetries })</code> is now <code>{ retries }</code>, with the same meaning (retries after the first send of each chat). <code>maxRetries</code> still works and is deprecated. The manager&#39;s <code>autoReconnect.maxRetries</code> is renamed the same way.</p><h2 id="whatsapp-flow-labels-default-to-english" tabindex="-1">WhatsApp Flow labels default to English <a class="header-anchor" href="#whatsapp-flow-labels-default-to-english" aria-label="Permalink to &quot;WhatsApp Flow labels default to English&quot;">​</a></h2><p><code>@botmesh/meta</code> builds the native WhatsApp Flow of a form with <code>toFlowJson()</code> and <code>provider.publishForm()</code>. The submit label is baked into the published Flow, and its default followed Spanish (<code>&#39;Enviar&#39;</code>) while the core moved to English. It now uses the core default locale: <code>&#39;Submit&#39;</code>. The fallbacks used when a bare form definition is sent without a bot context (<code>&#39;Open form&#39;</code>, <code>&#39;Fill in the form.&#39;</code>) follow too. To keep the Spanish labels:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toFlowJson</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(definition, { lang: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;es&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> CloudAPIProvider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config, lang: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;es&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// every publishForm() of this provider</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">provider.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">publishForm</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(definition, { lang: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;es&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// or one Flow</span></span></code></pre></div><p>The provider&#39;s <code>lang</code> is the language of your bot (<code>BotConfig.lang</code>): a bot with <code>lang: &#39;es&#39;</code> sets the same value on its <code>CloudAPIProvider</code>. A <code>submitLabel</code> on the definition always wins. Forms sent by a bot already use the user&#39;s <code>ctx.lang</code> for the button and the body.</p><h2 id="presence-hints-while-disconnected" tabindex="-1">Presence hints while disconnected <a class="header-anchor" href="#presence-hints-while-disconnected" aria-label="Permalink to &quot;Presence hints while disconnected&quot;">​</a></h2><p><code>ctx.typing()</code>, <code>ctx.recording()</code>, <code>ctx.markRead()</code> and the automatic typing indicator are best-effort hints. They used to behave differently per channel while the transport was down: Baileys did nothing, the REST channels called the API anyway and some rejected. There is now one rule (the &quot;PRESENCE WHILE DISCONNECTED&quot; section of the <code>IProvider</code> contract): while the provider&#39;s last connection state is not <code>&#39;ready&#39;</code>, or once the bot is stopped, the hint is skipped without error, logged at debug and counted in <code>metrics().presenceSkipped</code> (<code>botmesh_presence_skipped_total</code> in <code>toPrometheus()</code>). The 13 built-in providers follow it when called directly too. Once connected, a transport failure still rejects as before.</p><p>A custom provider should resolve <code>typing()</code> and <code>markRead()</code> without contacting its transport while it is not connected; <code>assertPresenceWhileDisconnected()</code> from <code>@botmesh/core/testing</code> checks it. A provider that never emits a connection event is not gated by the bot while it runs.</p><h2 id="stopping-event" tabindex="-1"><code>&#39;stopping&#39;</code> event <a class="header-anchor" href="#stopping-event" aria-label="Permalink to &quot;`&#39;stopping&#39;` event {#stopping-event}&quot;">​</a></h2><p><code>bot.stop()</code> on a running bot now emits <code>&#39;stopping&#39;</code> right after inbound is closed, before the drain and before the transport stops; <code>&#39;stopped&#39;</code> still comes last. Cancel long work there (model calls, downloads): the transport can still deliver what is in flight. <code>@botmesh/ai</code> aborts its in-flight model calls on <code>&#39;stopping&#39;</code> (it used to wait for <code>&#39;stopped&#39;</code>, after the transport had stopped).</p><h2 id="persistent-flows-checkpoint-when-they-start" tabindex="-1">Persistent flows checkpoint when they start <a class="header-anchor" href="#persistent-flows-checkpoint-when-they-start" aria-label="Permalink to &quot;Persistent flows checkpoint when they start&quot;">​</a></h2><p>A <code>.persistent()</code> flow now writes its checkpoint when it starts (step 0) as well as after every step, so a restart while its first step waits, typically a flow that opens with <code>.ask()</code>, resumes it there and asks again. It used to be lost unless durability or coordination was on. The cost is one more checkpoint write per flow entry.</p><h2 id="error-messages-without-chat-ids" tabindex="-1">Error messages without chat ids <a class="header-anchor" href="#error-messages-without-chat-ids" aria-label="Permalink to &quot;Error messages without chat ids&quot;">​</a></h2><p>The default messages of <code>OutsideSessionWindowError</code> and <code>RecipientUnreachableError</code> no longer include the chat id (it ended up in logs): they read <code>Outside the session window; a template is required</code> and <code>Recipient unreachable</code>. The id is still on <code>error.chatId</code>, and a message passed by the provider is kept as is.</p><h2 id="smaller-fixes" tabindex="-1">Smaller fixes <a class="header-anchor" href="#smaller-fixes" aria-label="Permalink to &quot;Smaller fixes&quot;">​</a></h2><ul><li><code>ctx.delete()</code> before <code>start()</code> or after <code>stop()</code> rejects with <code>BotNotRunningError</code> (<code>operation: &#39;delete&#39;</code>), like the sends.</li><li><code>IMessageContext.acknowledge</code> is typed as a required method: it always existed at runtime (a no-op without an interaction). <code>ctx.acknowledge?.()</code> still compiles.</li><li>A provider event whose <code>kind</code> is a string the core does not know is ignored with a debug line instead of being reported as an <code>InvalidProviderEventError</code>.</li><li><code>lang</code> and <code>i18n.defaultLocale</code> may name the same language with different precision (<code>&#39;es&#39;</code> and <code>&#39;es-MX&#39;</code>); the more specific tag becomes the default.</li><li>With <code>telemetry.ids: &#39;raw&#39;</code> and no <code>logIds</code>, log lines keep hashing ids (they used to reuse the raw span policy).</li><li><code>ChaosProvider.selfId</code> and <code>RecordingProvider.selfId</code> (<code>@botmesh/core/testing</code>) return <code>null</code> instead of <code>undefined</code> when the wrapped provider has no self id, so they implement <code>IProvider</code> under <code>exactOptionalPropertyTypes</code>.</li><li>In the durable outbox, a later part of a split text no longer overtakes an earlier part that is waiting for a retry, and the sweeper splits a journaled record that is over the channel&#39;s text limit (see <a href="/botmesh/guide/durability">Durable processing</a>). Waiting behind an earlier part costs no retry attempt, and the parts are linked by the new <code>OutboxRecord.previousPart</code> field (your own idempotency keys ending in <code>#&lt;n&gt;</code> are not treated as parts). A custom <code>OutboxJournal</code> should store <code>previousPart</code> from <code>put()</code> and honour the new <code>markFailed(..., { refund: true })</code> option (give the claimed attempt back); one that ignores them keeps the parts unordered on retries, as before.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./upgrade-channels-plugins">Upgrade notes: channels &amp; plugins</a></li><li><a href="./stable-migration">Upgrade to stable: checklist and API changes</a></li></ul>',57)])])}const g=t(i,[["render",d]]);export{u as __pageData,g as default};
